    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Find connected 8 components and key components by color. Compare size and
    # aspect ratio to identify the corresponding key piece, then paint its color.
    def comps(color):
        seen=set(); ans=[]
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                st=[(r,c)];seen.add((r,c));cells=[]
                while st:
                    y,x=st.pop();cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx));st.append((yy,xx))
                r0=min(y for y,x in cells);r1=max(y for y,x in cells);c0=min(x for y,x in cells);c1=max(x for y,x in cells)
                ans.append((cells,r1-r0+1,c1-c0+1,len(cells)))
        return ans
    key=[]
