def transform(grid):
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
    # Collect 4-connected colored key parts and summarize their dimensions.
    def get_components(color):
        seen=set(); ans=[]
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                stack=[(r,c)];seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop();cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx));stack.append((yy,xx))
                r0=min(y for y,x in cells);r1=max(y for y,x in cells);c0=min(x for y,x in cells);c1=max(x for y,x in cells)
                ans.append((cells,r1-r0+1,c1-c0+1))
        return ans
    # Locate each big rectangular block independently, including blocks that touch.
    # Input layout separates the three blocks by changes of row/column intervals.
    rows=[[(r,c) for c in range(w) if grid[r][c]==8] for r in range(h)]
    runs=[]
    for r,cells in enumerate(rows):
        if not cells: continue
        interval=(min(c for _,c in cells),max(c for _,c in cells))
        if runs and runs[-1][1]==r and runs[-1][2]==interval:
            runs[-1]=(runs[-1][0],r+1,interval)
        else:runs.append((r,r+1,interval))
    key=[]
    for color in range(1,8):
        key.extend((hh,ww,color) for cells,hh,ww in get_components(color))
    # Match each row-band to closest key component by aspect ratio.
    for r0,r1,(c0,c1) in runs:
        hh=r1-r0;ww=c1-c0+1
        if key:
            color=min(key,key=lambda k:abs(k[1]/k[0]-ww/hh))[2]
        else: color=8
        for r in range(r0,r1):
            for c in range(w):
                if grid[r][c]==8:out[r][c]=color
    return out
